1	import {
2	  INTERNAL_PAGE_IDS,
3	  TAB_SESSION_VERSION,
4	  createTabIdForTarget,
5	  getTabTargetKey,
6	  isHomeTarget,
7	  normalizeTabSessionSnapshot,
8	  type InternalPageId,
9	  type PageSessionState,
10	  type TabDescriptor,
11	  type TabSessionSnapshot,
12	  type TabTarget,
13	} from '../../../shared/contracts';
14	import { getTabTargetPageDefinition } from '../../pages/page-registry';
15	
16	export type TabState = TabSessionSnapshot;
17	
18	export type TabAction =
19	  | { type: 'open-page'; pageId: InternalPageId }
20	  | { type: 'open-target'; target: TabTarget }
21	  | { type: 'select-tab'; tabId: string }
22	  | { type: 'close-tab'; tabId: string }
23	  | { type: 'move-tab'; tabId: string; toIndex: number }
24	  | { type: 'update-scroll'; tabId: string; scrollTop: number }
25	  | {
26	      type: 'update-page-state';
27	      tabId: string;
28	      pageState: PageSessionState;
29	    }
30	  | { type: 'restore-session'; session: TabSessionSnapshot };
31	
32	function createDescriptor(target: TabTarget): TabDescriptor {
33	  const definition = getTabTargetPageDefinition(target);
34	
35	  return {
36	    tabId: createTabIdForTarget(target),
37	    target,
38	    scrollTop: 0,
39	    pageState: definition.createInitialState(),
40	  };
41	}
42	
43	export function createInitialTabState(): TabState {
44	  const home = createDescriptor({
45	    type: 'internal',
46	    pageId: INTERNAL_PAGE_IDS.home,
47	  });
48	
49	  return {
50	    version: TAB_SESSION_VERSION,
51	    tabs: [home],
52	    activeTabId: home.tabId,
53	  };
54	}
55	
56	export function normalizeRendererTabSession(
57	  session: unknown,
58	): TabSessionSnapshot {
59	  const normalized = normalizeTabSessionSnapshot(session);
60	
61	  if (!normalized) {
62	    return createInitialTabState();
63	  }
64	
65	  const targetKeys = new Set<string>();
66	  const tabs: TabDescriptor[] = [];
67	
68	  for (const tab of normalized.tabs) {
69	    const targetKey = getTabTargetKey(tab.target);
70	
71	    if (targetKeys.has(targetKey)) {
72	      continue;
73	    }
74	
75	    targetKeys.add(targetKey);
76	    const definition = getTabTargetPageDefinition(tab.target);
77	    tabs.push({
78	      ...tab,
79	      pageState: definition.migrateState(tab.pageState),
80	    });
81	  }
82	
83	  const firstTab = tabs[0];
84	
85	  if (!firstTab) {
86	    return createInitialTabState();
87	  }
88	
89	  return {
90	    version: TAB_SESSION_VERSION,
91	    tabs,
92	    activeTabId: tabs.some(({ tabId }) => tabId === normalized.activeTabId)
93	      ? normalized.activeTabId
94	      : firstTab.tabId,
95	  };
96	}
97	
98	function openTarget(state: TabState, target: TabTarget): TabState {
99	  const targetKey = getTabTargetKey(target);
100	  const existing = state.tabs.find(
101	    (tab) => getTabTargetKey(tab.target) === targetKey,
102	  );
103	
104	  if (existing) {
105	    return existing.tabId === state.activeTabId
106	      ? state
107	      : { ...state, activeTabId: existing.tabId };
108	  }
109	
110	  const tab = createDescriptor(target);
111	
112	  return {
113	    ...state,
114	    tabs: [...state.tabs, tab],
115	    activeTabId: tab.tabId,
116	  };
117	}
118	
119	function closeTab(state: TabState, tabId: string): TabState {
120	  const closingIndex = state.tabs.findIndex((tab) => tab.tabId === tabId);
121	
122	  if (closingIndex < 0) {
123	    return state;
124	  }
125	
126	  const closingTab = state.tabs[closingIndex];
127	
128	  if (
129	    state.tabs.length === 1 &&
130	    closingTab &&
131	    isHomeTarget(closingTab.target)
132	  ) {
133	    return state;
134	  }
135	
136	  const tabs = state.tabs.filter((tab) => tab.tabId !== tabId);
137	
138	  if (tabs.length === 0) {
139	    return createInitialTabState();
140	  }
141	
142	  const firstTab = tabs[0];
143	
144	  if (!firstTab) {
145	    return createInitialTabState();
146	  }
147	
148	  if (state.activeTabId !== tabId) {
149	    return { ...state, tabs };
150	  }
151	
152	  const neighbor = tabs[Math.min(closingIndex, tabs.length - 1)];
153	
154	  return {
155	    ...state,
156	    tabs,
157	    activeTabId: neighbor?.tabId ?? firstTab.tabId,
158	  };
159	}
160	
161	function moveTab(
162	  state: TabState,
163	  tabId: string,
164	  toIndex: number,
165	): TabState {
166	  const fromIndex = state.tabs.findIndex((tab) => tab.tabId === tabId);
167	  const boundedIndex = Math.max(
168	    0,
169	    Math.min(Math.trunc(toIndex), state.tabs.length - 1),
170	  );
171	
172	  if (fromIndex < 0 || fromIndex === boundedIndex) {
173	    return state;
174	  }
175	
176	  const tabs = [...state.tabs];
177	  const [tab] = tabs.splice(fromIndex, 1);
178	
179	  if (!tab) {
180	    return state;
181	  }
182	
183	  tabs.splice(boundedIndex, 0, tab);
184	
185	  return { ...state, tabs };
186	}
187	
188	function updateTab(
189	  state: TabState,
190	  tabId: string,
191	  update: (tab: TabDescriptor) => TabDescriptor,
192	): TabState {
193	  const index = state.tabs.findIndex((tab) => tab.tabId === tabId);
194	
195	  if (index < 0) {
196	    return state;
197	  }
198	
199	  const current = state.tabs[index];
200	
201	  if (!current) {
202	    return state;
203	  }
204	
205	  const next = update(current);
206	
207	  if (next === current) {
208	    return state;
209	  }
210	
211	  const tabs = [...state.tabs];
212	  tabs[index] = next;
213	  return { ...state, tabs };
214	}
215	
216	export function tabReducer(state: TabState, action: TabAction): TabState {
217	  switch (action.type) {
218	    case 'open-page':
219	      return openTarget(state, {
220	        type: 'internal',
221	        pageId: action.pageId,
222	      });
223	    case 'open-target':
224	      return openTarget(state, action.target);
225	    case 'select-tab':
226	      return state.tabs.some(({ tabId }) => tabId === action.tabId) &&
227	        action.tabId !== state.activeTabId
228	        ? { ...state, activeTabId: action.tabId }
229	        : state;
230	    case 'close-tab':
231	      return closeTab(state, action.tabId);
232	    case 'move-tab':
233	      return moveTab(state, action.tabId, action.toIndex);
234	    case 'update-scroll': {
235	      if (!Number.isFinite(action.scrollTop)) {
236	        return state;
237	      }
238	
239	      const scrollTop = Math.min(
240	        10_000_000,
241	        Math.max(0, action.scrollTop),
242	      );
243	      return updateTab(state, action.tabId, (tab) =>
244	        tab.scrollTop === scrollTop ? tab : { ...tab, scrollTop },
245	      );
246	    }
247	    case 'update-page-state':
248	      return updateTab(state, action.tabId, (tab) => ({
249	        ...tab,
250	        pageState: getTabTargetPageDefinition(tab.target).migrateState(
