156	export function ProjectTree({
157	  activeNodeId,
158	  controller,
159	  edit,
160	  onCancelEdit,
161	  onMoveNode,
162	  onOpenNode,
163	  onRequestCreate,
164	  onRequestMove,
165	  onRequestRename,
166	  onRequestTrash,
167	  onSubmitEdit,
168	  operationPending = false,
169	  translate,
170	}: ProjectTreeProps) {
171	  const [, renderVersion] = useReducer((version: number) => version + 1, 0);
172	  const [focusedNodeId, setFocusedNodeId] = useState<string>();
173	  const [draggedNodeId, setDraggedNodeId] = useState<string>();
174	  const [dropTargetId, setDropTargetId] = useState<string | null>();
175	  const itemRefs = useRef(new Map<string, HTMLDivElement>());
176	  const menuRefs = useRef(new Map<string, HTMLButtonElement>());
177	
178	  useEffect(() => controller.subscribe(renderVersion), [controller]);
179	  useEffect(() => {
180	    void controller.load(null);
181	  }, [controller]);
182	
183	  const visibleNodes = collectVisibleNodes(controller);
184	  const visibleNodeIds = useMemo(
185	    () => new Set(visibleNodes.map(({ node }) => node.nodeId)),
186	    [visibleNodes],
187	  );
188	  const effectiveFocusId =
189	    (focusedNodeId && visibleNodeIds.has(focusedNodeId)
190	      ? focusedNodeId
191	      : activeNodeId && visibleNodeIds.has(activeNodeId)
192	        ? activeNodeId
193	        : visibleNodes[0]?.node.nodeId) ?? undefined;
194	
195	  function focusNode(nodeId: string | undefined): void {
196	    if (!nodeId) {
197	      return;
198	    }
199	    setFocusedNodeId(nodeId);
200	    requestAnimationFrame(() => itemRefs.current.get(nodeId)?.focus());
201	  }
202	
203	  function handleNodeKeyDown(
204	    event: KeyboardEvent<HTMLDivElement>,
205	    visible: VisibleNode,
206	  ): void {
207	    if (event.defaultPrevented) {
208	      return;
209	    }
210	
211	    const index = visibleNodes.findIndex(
212	      ({ node }) => node.nodeId === visible.node.nodeId,
213	    );
214	
215	    switch (event.key) {
216	      case 'ArrowDown':
217	        event.preventDefault();
218	        focusNode(visibleNodes[index + 1]?.node.nodeId);
219	        return;
220	      case 'ArrowUp':
221	        event.preventDefault();
222	        focusNode(visibleNodes[index - 1]?.node.nodeId);
223	        return;
224	      case 'Home':
225	        event.preventDefault();
226	        focusNode(visibleNodes[0]?.node.nodeId);
227	        return;
228	      case 'End':
229	        event.preventDefault();
230	        focusNode(visibleNodes.at(-1)?.node.nodeId);
231	        return;
232	      case 'ArrowRight':
233	        if (visible.node.kind !== 'folder') {
234	          return;
235	        }
236	        event.preventDefault();
237	        if (!controller.isExpanded(visible.node.nodeId)) {
238	          void controller.setExpanded(visible.node.nodeId, true);
239	        } else {
240	          focusNode(visibleNodes[index + 1]?.node.nodeId);
241	        }
242	        return;
243	      case 'ArrowLeft':
244	        event.preventDefault();
245	        if (
246	          visible.node.kind === 'folder' &&
247	          controller.isExpanded(visible.node.nodeId)
248	        ) {
249	          void controller.setExpanded(visible.node.nodeId, false);
250	        } else {
251	          focusNode(visible.parentId ?? undefined);
252	        }
253	        return;
254	      case 'Enter':
255	      case ' ':
256	        event.preventDefault();
257	        if (visible.node.kind === 'folder') {
258	          void controller.toggle(visible.node.nodeId);
259	        } else {
260	          onOpenNode(visible.node);
261	        }
262	        return;
263	      case 'F2':
264	        event.preventDefault();
265	        onRequestRename(visible.node);
266	        return;
267	      case 'Delete':
