16	import { calculateMenuPosition, type MenuPlacement } from './menu-position';
17	import type { MenuItem } from './menu-types';
18	
19	type InitialFocus = 'first' | 'last' | 'none';
20	type Direction = 'next' | 'previous';
21	
22	interface MenuTreeProps {
23	  anchor: HTMLElement;
24	  ariaLabelledBy: string;
25	  id: string;
26	  initialFocus: InitialFocus;
27	  items: readonly MenuItem[];
28	  onAction: (id: string) => void;
29	  onClose: (restoreFocus: boolean) => void;
30	  onNavigateMenu?: (direction: Direction) => void;
31	}
32	
33	interface MenuSurfaceProps extends MenuTreeProps {
34	  anchor: HTMLElement;
35	  onRootElement?: (element: HTMLDivElement | null) => void;
36	  onCloseSubmenu?: (restoreFocus: boolean) => void;
37	  placement: MenuPlacement;
38	}
39	
40	interface OpenSubmenu {
41	  anchor: HTMLElement;
42	  id: string;
43	  initialFocus: InitialFocus;
44	  item: Extract<MenuItem, { kind: 'submenu' }>;
45	}
