47	function isInteractive(
48	  item: MenuItem,
49	): item is Exclude<MenuItem, { kind: 'separator' }> {
50	  return item.kind !== 'separator';
51	}
52	
53	function isDisabled(item: MenuItem): boolean {
54	  return item.kind !== 'separator' && Boolean(item.disabled);
55	}
56	
57	function itemId(item: Exclude<MenuItem, { kind: 'separator' }>): string {
58	  return item.id;
59	}
60	
61	function focusElement(element: HTMLElement | undefined): void {
62	  element?.focus();
63	}
64	
65	function ChevronRight() {
66	  return (
67	    <svg aria-hidden="true" viewBox="0 0 12 12">
68	      <path d="m4 2 4 4-4 4" />
69	    </svg>
70	  );
71	}
