73	function useMenuPosition(
74	  anchor: HTMLElement,
75	  placement: MenuPlacement,
76	): {
77	  menuRef: MutableRefObject<HTMLDivElement | null>;
78	  positioned: boolean;
79	  style: CSSProperties;
80	} {
81	  const menuRef = useRef<HTMLDivElement | null>(null);
82	  const [position, setPosition] = useState<{
83	    left: number;
84	    top: number;
85	  }>();
86	
87	  const updatePosition = useCallback(() => {
88	    const menu = menuRef.current;
89	
90	    if (!menu) {
91	      return;
92	    }
93	
94	    const next = calculateMenuPosition(
95	      anchor.getBoundingClientRect(),
96	      menu.getBoundingClientRect(),
97	      { width: window.innerWidth, height: window.innerHeight },
98	      placement,
99	    );
100	
101	    setPosition((current) =>
102	      current?.left === next.left && current.top === next.top
103	        ? current
104	        : { left: next.left, top: next.top },
105	    );
106	  }, [anchor, placement]);
107	
108	  useLayoutEffect(() => {
109	    updatePosition();
110	
111	    const resizeObserver =
112	      typeof ResizeObserver === 'undefined'
113	        ? undefined
114	        : new ResizeObserver(updatePosition);
115	    resizeObserver?.observe(anchor);
116	    if (menuRef.current) {
117	      resizeObserver?.observe(menuRef.current);
118	    }
119	
120	    window.addEventListener('resize', updatePosition);
121	    window.visualViewport?.addEventListener('resize', updatePosition);
122	    document.addEventListener('scroll', updatePosition, true);
123	
124	    return () => {
125	      resizeObserver?.disconnect();
126	      window.removeEventListener('resize', updatePosition);
127	      window.visualViewport?.removeEventListener('resize', updatePosition);
128	      document.removeEventListener('scroll', updatePosition, true);
129	    };
130	  }, [anchor, updatePosition]);
131	
132	  return {
133	    menuRef,
134	    positioned: Boolean(position),
135	    style: position
136	      ? { left: `${position.left}px`, top: `${position.top}px` }
137	      : { left: '0', top: '0' },
138	  };
139	}
