141	function MenuSurface({
142	  anchor,
143	  ariaLabelledBy,
144	  id,
145	  initialFocus,
146	  items,
147	  onAction,
148	  onClose,
149	  onCloseSubmenu,
150	  onNavigateMenu,
151	  onRootElement,
152	  placement,
153	}: MenuSurfaceProps) {
154	  const interactiveItems = useMemo(
155	    () => items.filter(isInteractive),
156	    [items],
157	  );
158	  const [activeId, setActiveId] = useState<string | undefined>(
159	    interactiveItems[0] ? itemId(interactiveItems[0]) : undefined,
160	  );
161	  const [openSubmenu, setOpenSubmenu] = useState<OpenSubmenu>();
162	  const itemRefs = useRef(new Map<string, HTMLButtonElement>());
163	  const typeahead = useRef({ query: '', timeout: 0 as ReturnType<typeof setTimeout> | 0 });
164	  const { menuRef, positioned, style } = useMenuPosition(anchor, placement);
165	
166	  const focusItem = useCallback(
167	    (idToFocus: string | undefined) => {
168	      if (!idToFocus) {
169	        return;
170	      }
171	
172	      setActiveId(idToFocus);
173	      requestAnimationFrame(() => focusElement(itemRefs.current.get(idToFocus)));
174	    },
175	    [],
176	  );
177	
178	  useLayoutEffect(() => {
179	    const target =
180	      initialFocus === 'last'
181	        ? interactiveItems.at(-1)
182	        : initialFocus === 'first'
183	          ? interactiveItems[0]
184	          : undefined;
185	
186	    if (target) {
187	      const targetId = itemId(target);
188	      const frame = requestAnimationFrame(() => {
189	        setActiveId(targetId);
190	        focusElement(itemRefs.current.get(targetId));
191	      });
192	
193	      return () => cancelAnimationFrame(frame);
194	    }
195	  }, [initialFocus, interactiveItems]);
196	
197	  useEffect(
198	    () => () => {
199	      if (typeahead.current.timeout) {
200	        clearTimeout(typeahead.current.timeout);
201	      }
202	    },
203	    [],
204	  );
205	
206	  function closeCurrentSubmenu(restoreFocus: boolean): void {
207	    const parent = openSubmenu?.anchor;
208	    setOpenSubmenu(undefined);
209	    if (restoreFocus) {
210	      requestAnimationFrame(() => focusElement(parent));
211	    }
212	  }
213	
214	  function openChild(
215	    item: Extract<MenuItem, { kind: 'submenu' }>,
216	    element: HTMLButtonElement,
217	    childInitialFocus: InitialFocus,
218	  ): void {
219	    if (item.disabled) {
220	      return;
221	    }
222	
223	    setActiveId(item.id);
224	    setOpenSubmenu({
225	      anchor: element,
226	      id: item.id,
227	      initialFocus: childInitialFocus,
228	      item,
229	    });
230	  }
231	
232	  function moveFocus(offset: number): void {
233	    if (interactiveItems.length === 0) {
234	      return;
235	    }
236	
237	    const index = interactiveItems.findIndex((item) => itemId(item) === activeId);
238	    const nextIndex =
239	      index < 0
240	        ? 0
241	        : (index + offset + interactiveItems.length) % interactiveItems.length;
242	    const next = interactiveItems[nextIndex];
243	    if (next) {
244	      setOpenSubmenu(undefined);
245	      focusItem(itemId(next));
246	    }
247	  }
248	
249	  function handleTypeahead(event: KeyboardEvent<HTMLButtonElement>): boolean {
250	    if (
251	      event.key.length !== 1 ||
252	      event.altKey ||
253	      event.ctrlKey ||
254	      event.metaKey
255	    ) {
256	      return false;
257	    }
258	
259	    const query = `${typeahead.current.query}${event.key}`.toLocaleLowerCase();
260	    const startIndex = interactiveItems.findIndex(
261	      (item) => itemId(item) === activeId,
262	    );
263	    const candidates = [
264	      ...interactiveItems.slice(startIndex + 1),
265	      ...interactiveItems.slice(0, startIndex + 1),
266	    ];
267	    const match = candidates.find((item) =>
268	      item.label.toLocaleLowerCase().startsWith(query),
269	    );
270	
271	    if (!match) {
272	      return false;
273	    }
274	
275	    event.preventDefault();
276	    typeahead.current.query = query;
277	    if (typeahead.current.timeout) {
278	      clearTimeout(typeahead.current.timeout);
279	    }
280	    typeahead.current.timeout = setTimeout(() => {
281	      typeahead.current.query = '';
282	      typeahead.current.timeout = 0;
283	    }, 700);
284	    setOpenSubmenu(undefined);
285	    focusItem(itemId(match));
286	    return true;
287	  }
288	
289	  function activateItem(
290	    item: Exclude<MenuItem, { kind: 'separator' }>,
291	    element: HTMLButtonElement,
292	  ): void {
293	    if (isDisabled(item)) {
294	      return;
295	    }
296	
297	    if (item.kind === 'submenu') {
298	      openChild(item, element, 'first');
299	      return;
300	    }
301	
302	    onClose(true);
303	    onAction(item.id);
304	  }
305	
306	  function handleItemKeyDown(
307	    event: KeyboardEvent<HTMLButtonElement>,
308	    item: Exclude<MenuItem, { kind: 'separator' }>,
309	  ): void {
310	    if (handleTypeahead(event)) {
311	      return;
312	    }
313	
314	    switch (event.key) {
315	      case 'ArrowDown':
316	        event.preventDefault();
317	        moveFocus(1);
318	        return;
319	      case 'ArrowUp':
320	        event.preventDefault();
321	        moveFocus(-1);
322	        return;
323	      case 'Home':
324	        event.preventDefault();
325	        focusItem(interactiveItems[0] ? itemId(interactiveItems[0]) : undefined);
326	        return;
327	      case 'End':
328	        event.preventDefault();
329	        focusItem(
330	          interactiveItems.at(-1)
331	            ? itemId(interactiveItems.at(-1)!)
332	            : undefined,
333	        );
334	        return;
335	      case 'ArrowRight':
336	        event.preventDefault();
337	        if (item.kind === 'submenu') {
338	          openChild(item, event.currentTarget, 'first');
339	        } else {
340	          onNavigateMenu?.('next');
341	        }
342	        return;
343	      case 'ArrowLeft':
344	        event.preventDefault();
345	        if (onCloseSubmenu) {
346	          onCloseSubmenu(true);
347	        } else {
348	          onNavigateMenu?.('previous');
349	        }
350	        return;
351	      case 'Enter':
352	      case ' ':
353	        event.preventDefault();
354	        activateItem(item, event.currentTarget);
355	        return;
356	      case 'Escape':
357	        event.preventDefault();
358	        if (onCloseSubmenu) {
359	          onCloseSubmenu(true);
360	        } else {
361	          onClose(true);
362	        }
363	        return;
364	      case 'Tab':
365	        window.setTimeout(() => onClose(false), 0);
366	        return;
367	      default:
368	        return;
369	    }
370	  }
371	
372	  return (
373	    <div
374	      aria-labelledby={ariaLabelledBy}
375	      className="flyoff-menu"
376	      data-positioned={positioned}
377	      id={id}
378	      ref={(element) => {
379	        menuRef.current = element;
380	        onRootElement?.(element);
381	      }}
382	      role="menu"
383	      style={style}
384	    >
385	      {items.map((item) => {
386	        if (item.kind === 'separator') {
387	          return (
388	            <div
389	              className="flyoff-menu__separator"
390	              key={item.id}
391	              role="separator"
392	            />
393	          );
394	        }
395	
396	        const disabled = isDisabled(item);
397	        const hasSubmenu = item.kind === 'submenu';
398	        const isSubmenuOpen = openSubmenu?.id === item.id;
399	
400	        return (
401	          <button
402	            aria-disabled={disabled || undefined}
403	            aria-controls={hasSubmenu ? `${id}-${item.id}` : undefined}
404	            aria-expanded={hasSubmenu ? isSubmenuOpen : undefined}
405	            aria-haspopup={hasSubmenu ? 'menu' : undefined}
406	            className={`flyoff-menu__item${
407	              item.kind === 'action' && item.tone === 'danger'
408	                ? ' flyoff-menu__item--danger'
409	                : ''
410	            }${disabled ? ' flyoff-menu__item--disabled' : ''}`}
411	            id={`${id}-item-${item.id}`}
412	            key={item.id}
413	            onClick={(event) => activateItem(item, event.currentTarget)}
414	            onKeyDown={(event) => handleItemKeyDown(event, item)}
415	            onMouseEnter={(event) => {
416	              setActiveId(item.id);
417	              if (item.kind === 'submenu') {
418	                openChild(item, event.currentTarget, 'none');
419	              } else {
420	                setOpenSubmenu(undefined);
421	              }
422	            }}
423	            ref={(element) => {
424	              if (element) {
425	                itemRefs.current.set(item.id, element);
426	              } else {
427	                itemRefs.current.delete(item.id);
428	              }
429	            }}
430	            role="menuitem"
431	            tabIndex={activeId === item.id ? 0 : -1}
432	            type="button"
433	          >
434	            <span className="flyoff-menu__item-label">{item.label}</span>
435	            {item.kind === 'action' && item.shortcut ? (
436	              <span className="flyoff-menu__shortcut">{item.shortcut}</span>
437	            ) : null}
438	            {hasSubmenu ? (
439	              <span className="flyoff-menu__submenu-indicator">
440	                <ChevronRight />
441	              </span>
442	            ) : null}
443	          </button>
444	        );
445	      })}
446	      {openSubmenu ? (
447	        <MenuSurface
448	          anchor={openSubmenu.anchor}
449	          ariaLabelledBy={`${id}-item-${openSubmenu.id}`}
450	          id={`${id}-${openSubmenu.id}`}
451	          initialFocus={openSubmenu.initialFocus}
452	          items={openSubmenu.item.children}
453	          onAction={onAction}
454	          onClose={onClose}
455	          onCloseSubmenu={closeCurrentSubmenu}
456	          onNavigateMenu={onNavigateMenu}
457	          placement="side-start"
458	        />
459	      ) : null}
460	    </div>
461	  );
462	}
463	
464	export function MenuTree({
465	  anchor,
466	  ariaLabelledBy,
467	  id,
468	  initialFocus,
469	  items,
470	  onAction,
471	  onClose,
472	  onNavigateMenu,
473	}: MenuTreeProps) {
474	  const rootRef = useRef<HTMLDivElement | null>(null);
475	
476	  useEffect(() => {
477	    const closeForExternalInteraction = (event: PointerEvent) => {
478	      const target = event.target;
479	
480	      if (
481	        target instanceof Node &&
482	        (rootRef.current?.contains(target) || anchor.contains(target))
483	      ) {
484	        return;
485	      }
486	
487	      onClose(false);
488	    };
489	    const closeForWindowBlur = () => onClose(false);
490	
491	    document.addEventListener('pointerdown', closeForExternalInteraction, true);
492	    window.addEventListener('blur', closeForWindowBlur);
493	
494	    return () => {
495	      document.removeEventListener(
496	        'pointerdown',
497	        closeForExternalInteraction,
498	        true,
499	      );
500	      window.removeEventListener('blur', closeForWindowBlur);
501	    };
502	  }, [anchor, onClose]);
503	
504	  return createPortal(
505	    <MenuSurface
506	      anchor={anchor}
507	      ariaLabelledBy={ariaLabelledBy}
508	      id={id}
509	      initialFocus={initialFocus}
510	      items={items}
511	      onAction={onAction}
512	      onClose={onClose}
513	      onNavigateMenu={onNavigateMenu}
514	      onRootElement={(element) => {
515	        rootRef.current = element;
516	      }}
517	      placement="bottom-start"
518	    />,
519	    document.body,
520	  );
521	}
