.flyoff-panel-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--sidebar-width);
  width: 10px;
  transform: translateX(-50%);
  z-index: 5;
  cursor: col-resize;
  touch-action: none;
}

.flyoff-panel-resizer::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  transform: translateX(-50%);
  background: transparent;
  transition: background 45ms ease-out;
}

.flyoff-panel-resizer:hover::before,
.flyoff-panel-resizer:focus-visible::before,
.flyoff-resizing .flyoff-panel-resizer::before {
  background: var(--color-accent);
}

.flyoff-panel-resizer:focus-visible {
  outline: 0;
}

.flyoff-panel-resizer:focus-visible::before {
  width: 2px;
  background: var(--color-focus-ring);
}

.flyoff-resizing {
  cursor: col-resize;
  user-select: none;
}

.flyoff-resizing .workspace {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .flyoff-panel-resizer::before {
    transition: none;
  }
}

