1	import { isProjectIdentifier } from './projects';
2	
3	export const TAB_SESSION_VERSION = 2 as const;
4	export const TAB_SESSION_MAX_TABS = 100;
5	export const TAB_SESSION_MAX_BYTES = 2 * 1024 * 1024;
6	
7	const LEGACY_TAB_SESSION_VERSION = 1 as const;
8	const MAX_IDENTIFIER_LENGTH = 256;
9	const MAX_PAGE_TYPE_LENGTH = 64;
10	
11	export const INTERNAL_PAGE_IDS = {
12	  home: 'home',
13	  thisDevice: 'this-device',
14	  settings: 'settings',
15	  help: 'help',
16	  updateApp: 'update-app',
17	} as const;
18	
19	export type InternalPageId =
20	  (typeof INTERNAL_PAGE_IDS)[keyof typeof INTERNAL_PAGE_IDS];
21	
22	export interface InternalTabTarget {
23	  type: 'internal';
24	  pageId: InternalPageId;
25	}
26	
27	export interface ProjectOverviewTabTarget {
28	  type: 'project-overview';
29	  projectId: string;
30	}
31	
32	export interface ProjectContentTabTarget {
33	  type: 'project-content';
34	  projectId: string;
35	  nodeId: string;
36	  pageType: string;
37	}
38	
39	export type ProjectTabTarget =
40	  | ProjectOverviewTabTarget
41	  | ProjectContentTabTarget;
42	
43	export type TabTarget = InternalTabTarget | ProjectTabTarget;
44	
45	export type JsonValue =
46	  | boolean
47	  | number
48	  | string
49	  | null
50	  | readonly JsonValue[]
51	  | { readonly [key: string]: JsonValue };
52	
53	export interface PageSessionState {
54	  version: number;
55	  data: JsonValue;
56	}
57	
58	export interface TabDescriptor {
59	  tabId: string;
60	  target: TabTarget;
61	  scrollTop: number;
62	  pageState: PageSessionState;
63	}
64	
65	export interface TabSessionSnapshot {
66	  version: typeof TAB_SESSION_VERSION;
67	  tabs: readonly TabDescriptor[];
68	  activeTabId: string;
69	}
70	
71	export type TabSessionRestoreDecision = 'restore' | 'ignore';
72	
73	export const GET_RESTORABLE_TAB_SESSION_CHANNEL =
74	  'flyoff:tabs:restore:get' as const;
75	export const RESOLVE_RESTORABLE_TAB_SESSION_CHANNEL =
76	  'flyoff:tabs:restore:resolve' as const;
77	export const SAVE_TAB_SESSION_CHANNEL = 'flyoff:tabs:session:save' as const;
78	
79	const internalPageIds = new Set<string>(Object.values(INTERNAL_PAGE_IDS));
80	
81	export function isInternalPageId(value: unknown): value is InternalPageId {
82	  return typeof value === 'string' && internalPageIds.has(value);
83	}
84	
85	function isSafeIdentifier(
86	  value: unknown,
87	  maximumLength = MAX_IDENTIFIER_LENGTH,
88	): value is string {
89	  return (
90	    typeof value === 'string' &&
91	    value.length > 0 &&
92	    value.length <= maximumLength &&
93	    /^[a-zA-Z0-9:_-]+$/.test(value)
94	  );
95	}
96	
97	function hasOnlyKeys(
98	  value: Record<string, unknown>,
99	  keys: readonly string[],
100	): boolean {
101	  const actualKeys = Object.keys(value);
102	  return (
103	    actualKeys.length === keys.length &&
104	    actualKeys.every((key) => keys.includes(key))
105	  );
106	}
107	
108	export function isTabTarget(value: unknown): value is TabTarget {
109	  if (!value || typeof value !== 'object') {
110	    return false;
111	  }
112	
113	  const target = value as Record<string, unknown>;
114	
115	  if (target.type === 'internal') {
116	    return (
117	      hasOnlyKeys(target, ['type', 'pageId']) &&
118	      isInternalPageId(target.pageId)
119	    );
120	  }
121	
122	  if (target.type === 'project-overview') {
123	    return (
124	      hasOnlyKeys(target, ['type', 'projectId']) &&
125	      isProjectIdentifier(target.projectId)
126	    );
127	  }
128	
129	  return (
130	    target.type === 'project-content' &&
131	    hasOnlyKeys(target, ['type', 'projectId', 'nodeId', 'pageType']) &&
132	    isProjectIdentifier(target.projectId) &&
133	    isProjectIdentifier(target.nodeId) &&
134	    isSafeIdentifier(target.pageType, MAX_PAGE_TYPE_LENGTH)
135	  );
136	}
137	
138	export function isProjectTarget(
139	  target: TabTarget,
140	): target is ProjectTabTarget {
141	  return target.type !== 'internal';
142	}
143	
144	export function isHomeTarget(target: TabTarget): boolean {
145	  return (
146	    target.type === 'internal' && target.pageId === INTERNAL_PAGE_IDS.home
147	  );
148	}
149	
150	export function getTabTargetKey(target: TabTarget): string {
151	  switch (target.type) {
152	    case 'internal':
153	      return `internal:${target.pageId}`;
154	    case 'project-overview':
155	      return `project-overview:${target.projectId}`;
156	    case 'project-content':
157	      return `project-content:${target.projectId}:${target.nodeId}`;
158	  }
159	}
160	
161	export function createTabIdForTarget(target: TabTarget): string {
162	  switch (target.type) {
163	    case 'internal':
164	      return `page:${target.pageId}`;
165	    case 'project-overview':
166	      return `project:${target.projectId}:overview`;
167	    case 'project-content':
168	      return `project:${target.projectId}:node:${target.nodeId}`;
169	  }
170	}
171	
172	function isJsonValue(
173	  value: unknown,
174	  depth = 0,
175	  budget = { remaining: 10_000 },
176	): value is JsonValue {
177	  if (depth > 20 || budget.remaining <= 0) {
178	    return false;
179	  }
180	
181	  budget.remaining -= 1;
182	
183	  if (
184	    value === null ||
185	    typeof value === 'boolean' ||
186	    typeof value === 'string'
187	  ) {
188	    return true;
189	  }
190	
191	  if (typeof value === 'number') {
192	    return Number.isFinite(value);
193	  }
194	
195	  if (Array.isArray(value)) {
196	    return value.every((entry) => isJsonValue(entry, depth + 1, budget));
197	  }
198	
199	  if (!value || typeof value !== 'object') {
200	    return false;
201	  }
202	
203	  return Object.entries(value).every(
204	    ([key, entry]) =>
205	      key.length <= MAX_IDENTIFIER_LENGTH &&
206	      isJsonValue(entry, depth + 1, budget),
207	  );
208	}
209	
210	function readPageState(
211	  value: unknown,
212	  recoverInvalid: boolean,
213	): PageSessionState | undefined {
214	  const state =
215	    value && typeof value === 'object'
216	      ? (value as Record<string, unknown>)
217	      : undefined;
218	
219	  if (
220	    state &&
221	    (recoverInvalid || hasOnlyKeys(state, ['version', 'data'])) &&
222	    Number.isSafeInteger(state.version) &&
223	    (state.version as number) >= 1 &&
224	    isJsonValue(state.data)
225	  ) {
226	    return {
227	      version: state.version as number,
228	      data: state.data,
229	    };
230	  }
231	
232	  return recoverInvalid ? { version: 1, data: null } : undefined;
233	}
234	
235	function readDescriptorFields(
236	  value: Record<string, unknown>,
237	  recoverInvalidPageState: boolean,
238	): Pick<TabDescriptor, 'tabId' | 'scrollTop' | 'pageState'> | undefined {
239	  const pageState = readPageState(value.pageState, recoverInvalidPageState);
240	
241	  if (
242	    !isSafeIdentifier(value.tabId) ||
243	    typeof value.scrollTop !== 'number' ||
244	    !Number.isFinite(value.scrollTop) ||
245	    value.scrollTop < 0 ||
246	    value.scrollTop > 10_000_000 ||
247	    !pageState
248	  ) {
249	    return undefined;
250	  }
251	
252	  return {
253	    tabId: value.tabId,
254	    scrollTop: value.scrollTop,
255	    pageState,
256	  };
257	}
258	
259	function readCurrentTabDescriptor(
260	  value: unknown,
261	  recoverInvalidPageState = false,
262	): TabDescriptor | undefined {
263	  if (!value || typeof value !== 'object') {
264	    return undefined;
265	  }
266	
267	  const tab = value as Record<string, unknown>;
268	  const fields = readDescriptorFields(tab, recoverInvalidPageState);
269	
270	  if (
271	    (!recoverInvalidPageState &&
272	      !hasOnlyKeys(tab, ['tabId', 'target', 'scrollTop', 'pageState'])) ||
273	    !fields ||
274	    !isTabTarget(tab.target)
275	  ) {
276	    return undefined;
277	  }
278	
279	  return { ...fields, target: tab.target };
280	}
281	
282	function readLegacyTabDescriptor(
283	  value: unknown,
284	  recoverInvalidPageState = false,
285	): TabDescriptor | undefined {
286	  if (!value || typeof value !== 'object') {
287	    return undefined;
288	  }
289	
290	  const tab = value as Record<string, unknown>;
291	  const fields = readDescriptorFields(tab, recoverInvalidPageState);
292	
293	  if (!fields || !isInternalPageId(tab.pageId)) {
294	    return undefined;
295	  }
296	
297	  if (
298	    tab.instanceKey !== undefined &&
299	    !isSafeIdentifier(tab.instanceKey)
300	  ) {
301	    return undefined;
302	  }
303	
304	  return {
305	    ...fields,
306	    target: { type: 'internal', pageId: tab.pageId },
307	  };
308	}
309	
310	function shouldKeepCurrentRawTab(value: unknown): boolean {
311	  if (!value || typeof value !== 'object') {
312	    return true;
313	  }
314	
315	  const target = (value as Record<string, unknown>).target;
316	
317	  if (!target || typeof target !== 'object') {
318	    return true;
319	  }
320	
321	  const rawTarget = target as Record<string, unknown>;
322	
323	  if (typeof rawTarget.type !== 'string') {
324	    return true;
325	  }
326	
327	  if (rawTarget.type === 'internal') {
328	    return (
329	      typeof rawTarget.pageId !== 'string' ||
330	      isInternalPageId(rawTarget.pageId)
331	    );
332	  }
333	
334	  return (
335	    rawTarget.type === 'project-overview' ||
336	    rawTarget.type === 'project-content'
337	  );
338	}
339	
340	function shouldKeepLegacyRawTab(value: unknown): boolean {
341	  if (!value || typeof value !== 'object') {
342	    return true;
343	  }
344	
345	  const pageId = (value as Record<string, unknown>).pageId;
346	  return typeof pageId !== 'string' || isInternalPageId(pageId);
347	}
348	
