2	  mkdirSync,
3	  readFileSync,
4	  renameSync,
5	  statSync,
6	  writeFileSync,
7	} from 'node:fs';
8	import path from 'node:path';
9	
10	import {
11	  hasRestorablePages,
12	  normalizeTabSessionSnapshot,
13	  TAB_SESSION_MAX_BYTES,
14	  type TabSessionSnapshot,
15	} from '../../shared/contracts';
16	
17	const TAB_SESSION_FILENAME = 'tab-session.json';
18	
19	export class TabSessionStore {
20	  readonly filePath: string;
21	
22	  private currentSession: TabSessionSnapshot | undefined;
23	  private pendingRestore: TabSessionSnapshot | undefined;
24	
25	  constructor(userDataPath: string) {
26	    this.filePath = path.join(userDataPath, TAB_SESSION_FILENAME);
27	
28	    const persisted = this.load();
29	    this.currentSession = persisted;
30	
31	    if (persisted && hasRestorablePages(persisted)) {
32	      this.pendingRestore = persisted;
33	    }
34	  }
35	
36	  getRestorableSession(): TabSessionSnapshot | null {
37	    return this.pendingRestore ?? null;
38	  }
39	
40	  beginWindowSession(): void {
41	    if (
42	      !this.pendingRestore &&
43	      this.currentSession &&
44	      hasRestorablePages(this.currentSession)
45	    ) {
46	      this.pendingRestore = this.currentSession;
47	    }
48	  }
49	
50	  resolveRestorableSession(session: TabSessionSnapshot): void {
51	    if (!this.pendingRestore) {
52	      throw new Error('There is no restorable tab session to resolve.');
53	    }
54	
55	    this.write(session);
56	    this.pendingRestore = undefined;
57	    this.currentSession = session;
58	  }
59	
60	  save(session: TabSessionSnapshot): void {
61	    if (this.pendingRestore) {
62	      throw new Error(
63	        'The previous tab session must be resolved before saving a new one.',
64	      );
65	    }
66	
67	    this.currentSession = session;
68	    this.write(session);
69	  }
70	
71	  saveFinal(session: TabSessionSnapshot): void {
72	    this.write(session);
73	    this.pendingRestore = undefined;
74	    this.currentSession = session;
75	  }
76	
77	  flush(): void {
78	    if (this.pendingRestore || !this.currentSession) {
79	      return;
80	    }
81	
82	    this.write(this.currentSession);
83	  }
84	
85	  private load(): TabSessionSnapshot | undefined {
86	    try {
87	      if (statSync(this.filePath).size > TAB_SESSION_MAX_BYTES) {
88	        return undefined;
89	      }
90	
91	      const value: unknown = JSON.parse(readFileSync(this.filePath, 'utf8'));
92	      return normalizeTabSessionSnapshot(value);
93	    } catch {
94	      return undefined;
95	    }
96	  }
97	
98	  private write(session: TabSessionSnapshot): void {
99	    mkdirSync(path.dirname(this.filePath), { recursive: true });
100	
101	    const temporaryPath = `${this.filePath}.${process.pid}.tmp`;
102	    const serialized = `${JSON.stringify(session, null, 2)}\n`;
103	
104	    if (Buffer.byteLength(serialized, 'utf8') > TAB_SESSION_MAX_BYTES) {
105	      throw new RangeError('The tab session exceeds the persistence limit.');
