}

export function adoptWorkspaceSnapshot(
  snapshot: WorkspaceSessionSnapshot,
): WorkspaceState {
  return {
    home: normalizeRendererTabSession(snapshot.home),
    project: snapshot.project
      ? adoptProjectWorkspace(snapshot.project)
