      type: 'open-target',
      target: {
        type: 'project-content',
        projectId: projectRef.current.projectId,
        nodeId: node.nodeId,
        pageType: node.pageType,
      },
    });
  },
  [cacheProjectNodes, dispatchGuardedTabAction],
);

