        ),
      ),
    ];
    const requestedNodeIds = new Set<string>();
    const restoredNodes: ProjectTreeNode[] = [];

    while (pendingNodeIds.length > 0) {
      const batch = pendingNodeIds.splice(0).filter((nodeId) => {
        if (requestedNodeIds.has(nodeId)) {
          return false;
